  expect(calls).toHaveLength(1024);
  record({ ...input, part: { ...part, id: "1024" } });
  record({ ...input, part: { ...part, id: "1" } });
  expect(calls).toHaveLength(1025);
  record({ ...input, part: { ...part, id: "0" } });
  expect(calls).toHaveLength(1026);
});
